// MOCK do node "Google Custom Search" (offline, sem chave/billing).
// No workflow REAL isto seria um HTTP Request para a Google Custom Search API.
// Aqui devolvemos resultados canned, na MESMA forma da API (campo "items").
const body = $json.body || {};
const company = body.company || 'Empresa Desconhecida';
const deal_id = body.deal_id || 'unknown';

const items = [
  { title: `${company} - Sobre`,      link: 'https://exemplo.com/sobre',
    snippet: `${company} atua em logistica com operacoes no Brasil e LatAm.` },
  { title: `${company} - Noticias`,   link: 'https://exemplo.com/news',
    snippet: `${company} captou Serie B e esta expandindo o time de engenharia.` },
  { title: `${company} - Tecnologia`, link: 'https://exemplo.com/tech',
    snippet: 'Stack citada publicamente: AWS, Salesforce, HubSpot.' },
];

return [{ json: { deal_id, company, items } }];

// MOCK do node "OpenAI Analisar Lead" (offline, sem API key, custo ZERO).
// No workflow REAL isto chamaria a OpenAI (um modelo GPT pequeno) e devolveria
// o JSON de enriquecimento. Para plugar o modelo de verdade, troque este
// Code node por um node OpenAI/HTTP Request apontando pra api.openai.com.
const { deal_id, company, items } = $json;

// score deterministico (0-100) derivado do deal_id (so digitos ASCII ->
// mesmo resultado em qualquer SO/terminal). Parece vivo, mas nao usa rede.
function scoreFrom(seed) {
  let s = 40;
  for (const ch of String(seed)) s = (s + ch.charCodeAt(0)) % 101;
  return Math.max(50, s);
}

const enrichment = {
  industry: 'Logistica',
  size_employees: '100-500',
  tech_stack: ['AWS', 'Salesforce', 'HubSpot'],
  buying_signals: ['captou Serie B', 'expandindo engenharia'],
  icp_match_score: scoreFrom(deal_id),
  talking_points: ['Mencionar caso de last-mile', 'Explorar integracao com HubSpot'],
  _modelo: 'GPT pequeno da OpenAI (MOCK — nenhuma chamada real foi feita)',
};

return [{ json: { deal_id, company_name: company, enrichment, raw_search_results: items } }];

// MOCK do node "Airtable Criar Registro" (offline, sem PAT).
// No workflow REAL isto seria Airtable > Append Record. Aqui apenas montamos
// a linha que SERIA gravada e seguimos em frente (simula sucesso).
const { deal_id, company_name, enrichment } = $json;
const e = enrichment || {};

const record = {
  deal_id,
  company_name,
  industry: e.industry,
  size_employees: e.size_employees,
  tech_stack: (e.tech_stack || []).join(', '),
  buying_signals: (e.buying_signals || []).join('; '),
  icp_match_score: e.icp_match_score,
  talking_points: (e.talking_points || []).join('; '),
  enriched_at: new Date().toISOString(),
};

return [{ json: { deal_id, company_name, enrichment: e, airtable_write: 'ok (MOCK)', record } }];

// MOCK do node "HubSpot Atualizar Deal" (offline, sem OAuth).
// No workflow REAL isto seria HubSpot > Update Deal (grava o icp_match_score
// no card do deal). Como e o ULTIMO node e o webhook responde com "lastNode",
// este JSON e o que volta no corpo da resposta do curl.
const { deal_id, enrichment } = $json;
const e = enrichment || {};

return [{ json: {
  status: 'enriched',
  hubspot_update: 'ok (MOCK)',
  deal_id,
  icp_match_score: e.icp_match_score,
  industry: e.industry,
  message: `Deal ${deal_id} enriquecido offline (sem custo). Score ICP = ${e.icp_match_score}.`,
} }];
